package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamTripitakaBank2 {
  private const val T = "ත්‍රිපිටකය හා ධර්ම සංගායනා ඉතිහාසය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("අභිධර්ම පිටකයේ හයවන ග්‍රන්ථය වන 'යමකප්පකරණය' එනමින් හැඳින්වීමට හේතුව කුමක්ද?", "ධර්ම කරුණු යුගල වශයෙන් විමසා පැහැදිලි කරන බැවින්", "යම රජු ගැන කියවෙන බැවින්", "ගාථා දෙක බැගින් ඇති බැවින්", "භික්ෂූන් දෙදෙනෙකු දෙසූ බැවින්", "මූල, ඛන්ධ, ආයතන ආදී යමක දහයකින් ප්‍රශ්න හා ප්‍රතිප්‍රශ්න විමසයි."),
    q("අභිධර්ම පිටකයේ තෙවන ග්‍රන්ථය වන 'ධාතුකථාව' මගින් ප්‍රධාන වශයෙන් විමසන්නේ කුමක්ද?", "ස්කන්ධ, ආයතන හා ධාතු අතර ඇති සම්බන්ධතාව", "විනය ශික්ෂාපද", "බුදු සිරුරේ ධාතු තැන්පත් කිරීම", "ජාතක කතා", "ධර්මයන් ස්කන්ධාදියෙහි සංග්‍රහ වන හා සම්ප්‍රයුක්ත වන අයුරු මෙහි දැක්වේ."),
    q("ත්‍රිපිටකයේ සඳහන් 'නෙත්තිප්පකරණය' හා 'පෙටකෝපදේශය' යන ග්‍රන්ථ රචනා කළේ කවුරුන් විසින් යැයි සැලකේද?", "මහා කච්චායන මහරහතන් වහන්සේ", "ආනන්ද හිමි", "උපාලි හිමි", "බුද්ධඝෝෂ හිමි", "සූත්‍ර ධර්ම අර්ථ විවරණය කිරීමේ ක්‍රමවේද දැක්වෙන මෙම ග්‍රන්ථ මියන්මාර ත්‍රිපිටකයේද අඩංගු වේ."),
    q("බුද්ධ ශාසනයේ චිරස්ථිතිය සඳහා අතිශය වැදගත් වූ 'තෙවන ධර්ම සංගායනාව' පැවැත්වෙන විට මගධයේ අගනුවර කුමක්ද?", "පැළලුප් නුවර (පාටලීපුත්‍ර)", "රජගහ නුවර", "විශාලා නුවර", "සැවැත් නුවර", "මෞර්ය අධිරාජ්‍යයේ අගනුවර වූ පැළලුප් නුවර අශෝකාරාමයේදී මෙය පැවැත්විණි."),
    q("ප්‍රථම ධර්ම සංගායනාවේදී 'මහා කාශ්‍යප හිමි' ආනන්ද හිමියන්ගෙන් චෝදනා පහ ගැන විමසූ විට ආනන්ද හිමි දැක්වූ ප්‍රතිචාරය කුමක්ද?", "වැරදි නොවුණත් සංඝ ගෞරවය උදෙසා දෙසා ගැනීම", "කෝප වී සංගායනාවෙන් ඉවත් වීම", "රජුට පැමිණිලි කිරීම", "මහා කාශ්‍යප හිමිට දොස් කීම", "ආනන්ද හිමියන්ගේ නිහතමානීත්වය හා සංඝ සමගිය මෙයින් ප්‍රකට විය."),
    q("ප්‍රථම ධර්ම සංගායනාවෙන් පසු සූත්‍ර පිටකය රැකගැනීමේ භාරකාරත්වය පවරන ලද්දේ කා හටද?", "ආනන්ද හිමියන්ගේ ශිෂ්‍ය පරපුරට", "උපාලි හිමියන්ගේ පරපුරට", "අනුරුද්ධ හිමියන්ගේ පරපුරට", "මහා කාශ්‍යප හිමියන්ට", "ආනන්ද හිමි සූත්‍ර පිටකය සංගායනා කළ බැවින් එය පවත්වා ගැනීම එතුමන්ගේ ශිෂ්‍යයන්ට පැවරිණි."),
    q("ප්‍රථම සංගායනාවේදී අංගුත්තර නිකාය පවත්වා ගෙන යෑමේ වගකීම භාර කළ මහතෙරුන් වහන්සේ කවුද?", "අනුරුද්ධ මහරහතන් වහන්සේගේ ශිෂ්‍ය පරපුරට", "සැරියුත් හිමිගේ පරපුරට", "මහා කච්චායන හිමිගේ පරපුරට", "රාහුල හිමිගේ පරපුරට", "දීඝ-ආනන්ද, මජ්ඣිම-සැරියුත් සිසුන්, සංයුත්ත-මහා කාශ්‍යප, අංගුත්තර-අනුරුද්ධ සිසුන් රැකගත්හ."),
    q("දීඝ නිකාය මුඛ පරම්පරාවෙන් රැකගැනීම භාර වූයේ කවර තෙරුන්ගේ ශිෂ්‍ය පරම්පරාවටද?", "ආනන්ද මහරහතන් වහන්සේගේ ශිෂ්‍ය පරපුරට", "මහා කාශ්‍යප හිමිගේ පරපුරට", "උපාලි හිමිගේ පරපුරට", "මුගලන් හිමිගේ පරපුරට", "දීඝභාණක පරම්පරාව ආනන්ද හිමි ඇසුරෙන් බිහි විය."),
    q("මජ්ඣිම නිකාය පවත්වා ගෙන යෑම සඳහා කවර තෙරුන්ගේ ශිෂ්‍ය පරම්පරාවට භාර කෙරුණිද?", "සැරියුත් මහරහතන් වහන්සේගේ ශිෂ්‍ය පරපුරට", "උපාලි හිමිගේ පරපුරට", "අනුරුද්ධ හිමිගේ පරපුරට", "පුණ්ණ හිමිගේ පරපුරට", "මජ්ඣිමභාණකයෝ සැරියුත් හිමියන්ගේ ශිෂ්‍ය පරපුරෙන් පැවත ආහ."),
    q("සංයුත්ත නිකාය කටපාඩමින් රැකගෙන පැමිණීමේ වගකීම පැවරුණේ කාගේ ශිෂ්‍ය පරපුරටද?", "මහා කාශ්‍යප මහරහතන් වහන්සේගේ ශිෂ්‍ය පරපුරට", "ආනන්ද හිමිගේ පරපුරට", "රාහුල හිමිගේ පරපුරට", "නන්ද හිමිගේ පරපුරට", "සංයුත්තභාණක පරපුර මහා කාශ්‍යප හිමියන්ගෙන් ඇරඹිණි."),
    q("ධර්ම සංගායනාවක් යන්නෙන් අදහස් කරන ප්‍රධාන කාර්යය කුමක්ද?", "සියලු භික්ෂූන් එක්ව බුද්ධ වචනය සාමූහිකව ගායනා කර පිරිසිදුව සම්මත කර ගැනීම", "තනි පුද්ගලයෙකු පොතක් ලිවීම", "සංගීත සංදර්ශනයක් පැවැත්වීම", "නව විහාරයක් විවෘත කිරීම", "'සංගීති' යනු සමගියෙන් එක්ව ධර්මය සජ්ඣායනා කොට තහවුරු කිරීමයි."),
    q("තෙවන ධර්ම සංගායනාව පැවැත්වෙන විට වසර හතක් නතර වී තිබූ ශාසනික විනය කර්මය කුමක්ද?", "උපෝසථ කර්මය", "කඨින පූජාව", "පිණ්ඩපාතය", "භාවනාව", "සිල්වත් භික්ෂූන් දුසිල්වතුන් සමඟ එක්වීම ප්‍රතික්ෂේප කළ බැවින් අශෝකාරාමයේ උපෝසථය නතර විය."),
    q("තෙවන සංගායනාවට පෙර රජුගේ ඇමතියෙකු උපෝසථ කර්මය කරවීමට ගොස් භික්ෂූන් ඝාතනය කළ විට රජු කා හමුවී සැක දුරු කර ගත්තේද?", "මොග්ගලීපුත්ත තිස්ස මහරහතන් වහන්සේ", "මහා කාශ්‍යප හිමි", "මිහිඳු හිමි", "උපගුප්ත හිමි", "රජුට සිදුවූයේ වැරදි අවබෝධයක්ද යන සැකය මොග්ගලීපුත්ත තිස්ස හිමි දුරු කළහ."),
    q("ධර්මාශෝක රජුගේ කාලයේ පිහිටුවන ලද ධර්ම විජය ප්‍රතිපත්තිය සඳහන් වන ලේඛන මොනවාද?", "අශෝක ගිරි ලිපි හා ටැම් ලිපි", "සීගිරි කුරුටු ගී", "තෝනිගල සෙල්ලිපිය", "ගල් විහාර සෙල්ලිපිය", "භබෲ සෙල්ලිපිය වැනි අශෝක ලේඛනවල බෞද්ධ සූත්‍ර නාම පවා සඳහන් වේ."),
    q("අශෝක අධිරාජ්‍යයා සාමාන්‍ය ජනයාට හා භික්ෂූන්ට නිතර කියවා මෙනෙහි කරන ලෙස නිර්දේශ කළ සූත්‍ර හතක් ඇතුළත් සෙල්ලිපිය කුමක්ද?", "භබෲ (කල්කටා බෛරාත්) සෙල්ලිපිය", "මස්කි සෙල්ලිපිය", "ලුම්බිණි ටැම් ලිපිය", "සාරානාත් ටැම් ලිපිය", "මුනි ගාථා, උපතිස්ස පසින ආදී ධර්ම පරියාය 7 ක් එහි නම් කර ඇත."),
    q("බුදුරදුන් උපන් ලුම්බිණි ග්‍රාමයේ බදු ලිහිල් කළ බවට අශෝක රජු පිහිටුවූ ලිපිය කුමක්ද?", "රුම්මින්දේයි ටැම් ලිපිය", "ගිර්නාර් ලිපිය", "කාලිංග ලිපිය", "ඇලහැර ලිපිය", "'ඉධ බුධේ ජාතේ සක්‍යමුනිති' යනුවෙන් බුදුන් උපන් තැන එහි තහවුරු කර ඇත."),
    q("ථේරවාද බුදුදහම හැර පසුකාලීනව භාරතයේ බිහි වූ නිකාය ගණන කීයක් ලෙස සාම්ප්‍රදායිකව සැලකේද?", "අටළොස් නිකාය (නිකාය 18)", "දෙකකි", "පහකි", "විස්සකි", "ථේරවාද හා මහාසාංඝික මූල නිකායන්ගෙන් පසුව නිකාය 18 ක් පැන නැගුණි."),
    q("දෙවන ධර්ම සංගායනාව පිළිබඳව සඳහන් වන ප්‍රධාන පාලි විනය කොටස කුමක්ද?", "චුල්ලවග්ග පාලියේ සත්තසතික ඛන්ධකය", "මහාවග්ග පාලිය", "පරිවාර පාලිය", "ධම්මසංගණිය", "පළමු හා දෙවන සංගායනා පිළිබඳ විස්තර චුල්ලවග්ග පාලියේ අවසාන ඛන්ධක දෙකේ එයි."),
    q("මහාවංශයේ සඳහන් වන පරිදි වළගම්බා රජු දවස ඇති වූ දොළොස් අවුරුදු මහා දුර්භික්ෂය කුමක්ද?", "බැමිණිතියා සාය", "කළුදිය සාය", "මහා නියඟය", "ගංවතුර විපත", "මෙම දුර්භික්ෂ සමයේ බොහෝ භික්ෂූන් ඉන්දියාවට වැඩි අතර පිරිසක් මෙරට දහම රැක්කාහ."),
    q("බැමිණිතියා සාය සමයේදී ගස්වල කොළ පොතු පවා වළඳමින් ත්‍රිපිටකය රැකගත් ස්ථානයක් ලෙස ප්‍රකට වන්නේ කුමක්ද?", "දක්ඛිණ මලය රට හා තිස්සමහාරාමය", "යාපනය", "කැලණිය", "මඩකලපුව", "අතිශය දුෂ්කරතා මැද ලක්දිව භික්ෂූන් ත්‍රිපිටකය කටපාඩමින් රැකගත්හ."),
    q("වළගම්බා රජු සමයේ ත්‍රිපිටකය ග්‍රන්ථාරූඪ කිරීමේදී මතු වූ වැදගත් ශාසනික විවාදය කුමක්ද?", "පරියත්තිය (ඉගෙනීම) ද නැතහොත් පටිපත්තිය (පිළිවෙත) ද ශාසනයේ මුල යන්න", "භික්ෂුණී පැවිද්ද", "සිවුරේ වර්ණය", "ආරාම ඉදි කිරීම", "අවසානයේ පරියත්තිය හෙවත් ධර්ම ග්‍රන්ථ රැකීම ශාසනයේ මුල බව තීරණය විය."),
    q("බුද්ධඝෝෂ හිමියන්ට අමතරව අනුරාධපුර සමයේ ත්‍රිපිටක ග්‍රන්ථවලට අටුවා ලියූ තවත් මහා පඬිවරයෙකු කවුද?", "බුද්ධදත්ත හිමි", "වැලිවිට සරණංකර හිමි", "හික්කඩුවේ සුමංගල හිමි", "තොටගමුවේ රාහුල හිමි", "උත්තරවිනිච්ඡය, විනයවිනිච්ඡය හා අභිධම්මාවතාරය බුද්ධදත්ත හිමිගේ කෘති වේ."),
    q("ක්‍රි.ව. 12 වන සියවසේ මහා පරාක්‍රමබාහු රජුගේ ප්‍රධානත්වයෙන් සංඝ සමගිය ඇති කිරීමට මූලික වූ මහතෙරුන් කවුද?", "දිඹුලාගල මහා කාශ්‍යප හිමි", "තොටගමුවේ රාහුල හිමි", "බුද්ධඝෝෂ හිමි", "වීදාගම මෛත්‍රෙය හිමි", "නිකාය තුන සමගි කොට පොළොන්නරු කතිකාවත පිහිටුවීමට මහා කාශ්‍යප හිමි මුල් වූහ."),
    q("පොළොන්නරු යුගයේ ටීකා රචනා කිරීමේ පුරෝගාමියා වූ දිඹුලාගල මහා කාශ්‍යප හිමියන්ගේ ප්‍රධාන ශිෂ්‍යයා කවුද?", "සාරිපුත්ත මහතෙරුන් වහන්සේ", "මොග්ගල්ලාන හිමි", "සුමංගල හිමි", "වචිස්සර හිමි", "සාරත්ථදීපනී විනය ටීකාව ඇතුළු ටීකා රැසක් සාරිපුත්ත හිමි රචනා කළහ."),
    q("විනය පිටකයේ සමන්තපාසාදිකා අටුවාවට ලියැවුණු ප්‍රධාන පාලි ටීකාව කුමක්ද?", "සාරත්ථදීපනිය", "සීලක්ඛන්ධ ටීකාව", "අත්ථසාලිනී ටීකාව", "ධම්මපද ටීකාව", "පොළොන්නරුවේ සාරිපුත්ත හිමියන් විසින් සාරත්ථදීපනිය රචනා කරන ලදී."),
    q("ලෝකයේ බෞද්ධ සාහිත්‍යයේ කිසිදු වෙනස්කමකින් තොරව ආරක්ෂා වූ පැරණිතම සම්පූර්ණ බුද්ධ ධර්ම සංග්‍රහය කුමක්ද?", "පාලි ත්‍රිපිටකය", "සංස්කෘත වංශකතා", "ටිබෙට් කංජුර්", "චීන ආගම", "පාලි ත්‍රිපිටකය මුල් බුද්ධ ධර්මයට වඩාත්ම සමීප ලේඛනය ලෙස ලොව පිළිගනී."),
    q("සූත්‍ර පිටකයේ දීඝ නිකායට හා සෙසු නිකායන්ට අයත් සූත්‍ර අතර 'මහා සමය සූත්‍රය' දේශනා කළ ස්ථානය කුමක්ද?", "කපිලවස්තුවේ මහාවනය", "රජගහ නුවර", "සැවැත් නුවර", "කුසිනාරාව", "දසදහසක් සක්වළ දෙව් බඹුන් රැස්වූ කපිලවස්තු මහාවනයේදී මෙය දේශනා විය."),
    q("පිටක ග්‍රන්ථ හැදෑරීමේදී මූලික වශයෙන් උපකාරී වන පැරණි සිංහල අර්ථ විවරණ ග්‍රන්ථ හඳුන්වන්නේ කෙසේද?", "සන්න හා ගැටපද", "සන්දේශ", "හටන් කාව්‍ය", "ප්‍රශස්ති", "ධම්පියා අටුවා ගැටපදය, ජාතක අටුවා ගැටපදය වැනි ග්‍රන්ථ ත්‍රිපිටකය හැදෑරීමට උපකාරී වේ."),
    q("පස්වන ධර්ම සංගායනාව (1871 දී) පවත්වා මුළු ත්‍රිපිටකයම කිරිගරුඬ පුවරු 729 ක කොටා තැන්පත් කළ රට කුමක්ද?", "මියන්මාරය (බුරුමයේ මැන්ඩලේ නුවර)", "තායිලන්තය", "ශ්‍රී ලංකාව", "ඉන්දියාව", "මින්දොන් මින් රජුගේ අනුග්‍රහයෙන් කුතෝඩෝ විහාරයේ ලෝකයේ විශාලතම පොත ලෙස මෙය කෙරිණි."),
    q("සිංහල ජාතක පොත රචනා කිරීමේදී මූලාශ්‍ර කරගත් පාලි ග්‍රන්ථය කුමක්ද?", "පාලි ජාතකට්ඨකථාව", "විමානවත්ථුව", "චරියාපිටකය", "අපදානය", "පන්සිය පනස් ජාතක පොතට මූලික වූයේ පාලි ජාතකට්ඨකථාවයි."),
    q("ත්‍රිපිටකයේ සඳහන් 'සූත්‍ර' යන වචනයේ අර්ථ විවරණය කුමක්ද?", "අර්ථයන් නූලකින් මෙන් මනාව අමුණා දැක්වෙන දේශනා", "පැරණි ගීත", "රාජ නීති", "සටන් කතා", "මල් මාලාවක් නූලෙන් රඳවන්නා සේ ධර්ම කරුණු විසිරී නොයා රඳවා තබන්නේ සූත්‍රයයි."),
    q("විනය පිටකයේ සඳහන් 'සංඝාදිසේස' ඇවැත් ගණන භික්ෂූන් සඳහා කීයක් වේද?", "දහතුනකි (13)", "හතරකි", "අනූ දෙකකි", "සැටකි", "මෙම ඇවතකට පත් වූ භික්ෂුවකට සංඝයාගේ මැදිහත්වීමෙන් පිරිවෙස් පුරා පිරිසිදු විය හැකිය."),
    q("විනය පිටකයේ භික්ෂුවකගේ සිවුරු, පාත්‍ර, සෙනසුන් හා බෙහෙත් යන සිව්පසය සම්බන්ධ නීති දැක්වෙන ග්‍රන්ථය කුමක්ද?", "මහාවග්ග පාලිය", "පාරාජිකා පාලිය", "පරිවාර පාලිය", "ධම්මසංගණිය", "චීවරක්ඛන්ධක, භේසජ්ජක්ඛන්ධක ආදිය මහාවග්ග පාලියේ එයි."),
    q("භික්ෂූන් වහන්සේලාගේ උපසම්පදා විනය කර්මය පවත්වන ස්ථානය හෙවත් සීමා මාලක පිළිබඳ විස්තර එන්නේ කුමන විනය කොටසේද?", "මහාවග්ග පාලියේ උපෝසථක්ඛන්ධකයේ", "චුල්ලවග්ග පාලියේ", "පාරාජිකා පාලියේ", "පරිවාර පාලියේ", "උපසම්පදා ක්‍රමවේදය මහාවග්ග පාලියේ මහාක්ඛන්ධකයේ දැක්වේ."),
    q("සංඝ සමාජයේ විනය ප්‍රශ්න නිරාකරණය කරන සප්ත අධිකරණ සමථ ධර්ම විස්තර වන්නේ කොහිද?", "චුල්ලවග්ග පාලියේ සමථක්ඛන්ධකයේ", "සූත්‍ර පිටකයේ", "අභිධර්මයේ", "ධම්මපදයේ", "සම්මුඛාවිනය, සතිවිනය ආදී සත් වැදෑරුම් සමථ ධර්ම විනය පිටකයේ එයි."),
    q("බුදුරදුන් සමයේ ජීවත් වූ රහතන් වහන්සේලාගේ පෙර ජීවිත කතා හා කුසල කර්ම දැක්වෙන ඛුද්දක නිකාය ග්‍රන්ථය කුමක්ද?", "අපදාන පාලිය", "බුද්ධවංසය", "චරියාපිටකය", "විමානවත්ථු", "ථේරාපදාන හා ථේරීඅපදාන වශයෙන් රහතුන්ගේ පෙර පින්කම් එහි දැක්වේ."),
    q("ඛුද්දක නිකායේ 'සුත්ත නිපාතය' ප්‍රධාන වග්ග කීයකින් සමන්විත වේද?", "පහකින්", "දෙකකින්", "හතකින්", "දහයකින්", "උරග, චූළ, මහා, අට්ඨක, පාරායන යන වග්ග 5 න් යුක්තය."),
    q("බුදුරදුන්ගේ දේශනා ක්‍රම අතරින් 'සම්මුති දේශනා' හා 'පරමත්ථ දේශනා' යනු කුමක්ද?", "ලෝක ව්‍යවහාරයෙන් දෙසූ සූත්‍ර හා ස්කන්ධාදී පරමාර්ථයෙන් දෙසූ අභිධර්මය", "පැරණි හා නව දේශනා", "පාලි හා සිංහල දේශනා", "දීර්ඝ හා කෙටි දේශනා", "මිනිසා, ගස, සත්වයා යැයි දේශනා කිරීම සම්මුතිය වන අතර චිත්ත චෛතසික ලෙස දෙසීම පරමාර්ථයයි."),
    q("පළමු ධර්ම සංගායනාවේදී 'වස්සාවාස' හෙවත් වස් සමාදාන කාලය තුළ පිළිසකර කළ විහාර පිහිටියේ කොහිද?", "රජගහ නුවර අවට විහාර දහඅටක්", "සැවැත් නුවර", "විශාලා නුවර", "කපිලවස්තුවේ", "අජාසත් රජු විසින් රජගහ නුවර පැරණි විහාර 18 ක් ප්‍රතිසංස්කරණය කරවීය."),
    q("දෙවන ධර්ම සංගායනාවේදී දස අකැප වස්තු විනිශ්චය කිරීමට නැගෙනහිර හා බටහිර භික්ෂූන්ගෙන් පත් කළ කමිටුවේ සාමාජිකයන් ගණන කීයද?", "අට නමකි (උබ්බාහිකා කමිටුව)", "දෙදෙනෙකි", "විසි නමකි", "සිය නමකි", "ප්‍රාචීන 4 ක් හා පාචීන 4 ක් වශයෙන් අට නමක් වාලුකාරාමයේදී තීරණය ගත්හ."),
    q("දෙවන සංගායනාවේදී වජ්ජිපුත්තකයන් ඉදිරිපත් කළ 'කප්පති සිංගිලෝණ කප්පෝ' යන්නෙන් අදහස් කළේ කුමක්ද?", "අඟක තබාගෙන ලුණු භාවිත කිරීම කැප බව", "රන් රිදී පිළිගැනීම", "දියර මත්පැන් පානය", "සවස් කාලයේ ආහාර ගැනීම", "පසු දිනකට කැප නොවන ආහාර වර්ග තබා ගැනීම විනය විරෝධී බව තීරණය විය."),
    q("දෙවන සංගායනාවේ 'ද්වංගුල කප්ප' යන අකැප වස්තුව කුමක්ද?", "හිරු අවරට ගොස් අඟල් දෙකක් සෙවණැල්ල දික් වන තෙක් ආහාර වැළඳීම", "දෙවරක් නෑම", "සිවුරු දෙකක් පෙරවීම", "දෙදෙනෙකු එක්ව යෑම", "මධ්‍යාහ්නයෙන් පසු විකාලයේ ආහාර වැළඳීම අකැප බව සංගායනාවේදී තහවුරු කෙරිණි."),
    q("තෙවන ධර්ම සංගායනාවෙන් පසු මිහිඳු හිමියන් මුලින්ම ලංකාවේදී දේශනා කළ සූත්‍රය කුමක්ද?", "චූළහත්ථිපදෝපම සූත්‍රය", "සමචිත්තපරියාය සූත්‍රය", "දේවදූත සූත්‍රය", "බාලපණ්ඩිත සූත්‍රය", "මිහින්තලයේදී දේවානම්පියතිස්ස රජුට තෙරුවන් ගුණ පැහැදිලි කරමින් මෙය දෙසූහ."),
    q("මාතලේ අලුවිහාරයේදී ත්‍රිපිටකය ලිවීමට භාවිත කළ මූලික ලේඛන මාධ්‍යය කුමක්ද?", "තල කොළ (පුස්කොළ පොත්)", "තඹ තහඩු", "කඩදාසි", "මැටි පුවරු", "පදම් කළ තල කොළවල පන්හිඳෙන් ලියා කළුමැද ත්‍රිපිටකය සුරැක්කේය."),
    q("බුද්ධඝෝෂ හිමියන් පැමිණීමට පෙර අනුරාධපුරයේ තිබූ හෙළ අටුවා අතර ප්‍රධාන වූ මූලාශ්‍ර තුන මොනවාද?", "මහා අට්ඨකථා, මහාපච්චරිය හා කුරුන්දි අට්ඨකථා", "සමන්තපාසාදිකා, විසුද්ධිමග්ග, ටීකා", "සද්ධර්මරත්නාවලිය, පූජාවලිය", "මහාවංසය, දීපවංසය, බෝධිවංසය", "මෙම හෙළ අටුවා භාවිත කර පසුව පාලි අටුවා රචනා විය."),
    q("බුද්ධඝෝෂ හිමියන් හෙළ අටුවා පාලියට පරිවර්තනය කිරීමේදී මහාවිහාර භික්ෂූන් සමඟ කටයුතු කළ ප්‍රධාන ස්ථානය කුමක්ද?", "මහාප්‍රධාන ඝරය හා ග්‍රන්ථාකර පිරිවෙන (අනුරාධපුර මහාවිහාරය)", "ජේතවනාරාමය", "අභයගිරිය", "දඹුලු විහාරය", "මහාවිහාරවාසී සංඝපාල හිමියන්ගෙන් අවසර ලබා පරිවර්තන කටයුතු සිදු කළහ."),
    q("බුද්ධඝෝෂ හිමියන් විසින් රචනා කළ 'අත්ථසාලිනී' යනු කුමන ග්‍රන්ථයේ අටුවාවද?", "ධම්මසංගණීප්පකරණයේ", "විභංගප්පකරණයේ", "පට්ඨානප්පකරණයේ", "දීඝ නිකායේ", "අභිධර්ම පිටකයේ මුල් ග්‍රන්ථයට අත්ථසාලිනියත්, විභංගයට සම්මෝහවිනෝදනියත් ලියූහ."),
    q("සම්මෝහවිනෝදනිය යනු අභිධර්ම පිටකයේ කවර ග්‍රන්ථයට ලියූ පාලි අටුවාවද?", "විභංගප්පකරණයට", "ධාතුකථාවට", "කථාවත්ථුවට", "ධම්මසංගණියට", "අභිධර්ම පිටකයේ ඉතිරි ග්‍රන්ථ පහට පංචප්පකරණට්ඨකථාව රචනා කර ඇත."),
    q("ධර්ම සංගායනාවක් නොවුණත් ශ්‍රී ලංකාවේ ශාසන විනය පිරිසිදු කිරීමට රජු හා මහා සංඝයා එක්ව සම්මත කළ නීති මාලාව කුමක්ද?", "කතිකාවත්", "සන්දේශ", "අස්න", "සන්නස", "මහා පරාක්‍රමබාහු, දඹදෙණි, කීර්ති ශ්‍රී රාජසිංහ ආදී කතිකාවත් පැවතුණි."),
    q("කාලාශෝක රජුගේ සමයේ විසූ දෙවන සංගායනාවේදී පරාජිත වජ්ජිපුත්තක භික්ෂූන් සිදු කළ වෙනස්කම් නිසා රැකුණු මුල් බුදුදහම හැඳින්වෙන්නේ කෙසේද?", "ථේරවාද සම්ප්‍රදාය", "මහාසාංඝික සම්ප්‍රදාය", "වජ්‍රයාන සම්ප්‍රදාය", "තන්ත්‍රයාන සම්ප්‍රදාය", "මහා කාශ්‍යප ආදී මහතෙරුන්ගේ මතය රැකගත් බැවින් ථේරවාදය නම් විය."),
    q("ශ්‍රී ලංකාවේදී රචනා වූ පළමු පාලි අටුවාව ලෙස සැලකෙන බුද්ධඝෝෂ හිමිගේ විසුද්ධිමග්ගය කොටස් කීයකින් සමන්විතද?", "තුනකින් (සීල, සමාධි, ප්‍රඥා)", "හතරකින්", "පහකින්", "දහයකින්", "සමස්ත ත්‍රිපිටකයේම සාරය සීල, සමාධි, ප්‍රඥා ලෙස විසුද්ධිමග්ගයේ විග්‍රහ වේ."),
    q("දීඝ නිකායේ අවසාන සූත්‍ර දෙක වන සංගීති හා දසඋත්තර සූත්‍ර සම්පාදනය කළ මහරහතන් වහන්සේ කවුද?", "සැරියුත් මහරහතන් වහන්සේ", "ආනන්ද හිමි", "මුගලන් හිමි", "රාහුල හිමි", "ධර්ම සංගායනාවක මූලික ආකෘතියක් සැරියුත් හිමියන් එමගින් පෙන්වා දුන්හ."),
    q("බුද්ධ ශාසනයේ ත්‍රිවිධ ශික්ෂාව වන සීල, සමාධි, ප්‍රඥා ත්‍රිපිටකයට සම්බන්ධ වන ආකාරය කුමක්ද?", "විනය පිටකය සීලයටත්, සූත්‍ර පිටකය සමාධියටත්, අභිධර්මය ප්‍රඥාවටත්ය", "විනය ප්‍රඥාවට පමණි", "සූත්‍ර පිටකය විනයට පමණි", "අභිධර්මය සීලයට පමණි", "ත්‍රිපිටකයම ත්‍රිවිධ ශික්ෂාව සම්පූර්ණ කිරීමට මඟ පෙන්වයි."),
    q("සංස්කෘත හා චීන පරිවර්තනවලට පෙරාතුව බුදුරදුන් දේශනා කළ මුල් පාලි භාෂාව හැඳින්වූයේ කුමන නමින්ද?", "මාගධී භාෂාව", "ද්‍රවිඩ භාෂාව", "ප්‍රාකෘත භාෂාව", "ලාට භාෂාව", "මගධ දේශයේ ව්‍යවහාර වූ පාලි (මාගධී) බසින් ත්‍රිපිටකය ආරක්ෂා වී ඇත."),
    q("කිසිදු භික්ෂුවකට තම අභිමතය පරිදි බුද්ධ වචනය වෙනස් කිරීමට හෝ අකැප දේ ඇතුළත් කිරීමට නොහැකි වන සේ සකස් කළ මිනුම් දණ්ඩ කුමක්ද?", "සතර මහාපදේශ", "සතර ඉර්දිපාද", "සතර සංග්‍රහ වස්තු", "සතර අගති", "බුදු, සංඝ, සමූහ, බහුශ්‍රුත යන මූලාශ්‍රවලින් පැවසුවත් සූත්‍ර විනයට ගළපා බැලිය යුතු බව වදාළහ."),
    q("මහාපරිනිබ්බාන සූත්‍රයේ සඳහන් 'සතර මහාපදේශ' මගින් අවධාරණය කරන්නේ කුමක්ද?", "කවුරුන් කීවත් සූත්‍රයේ බහා බලා විනයෙහි සසඳා බලා සත්‍යය තහවුරු කර ගත යුතු බව", "වැඩිහිටියන් කියන ඕනෑම දෙයක් පිළිගත යුතු බව", "පැරණි පොත් ඉවත දැමිය යුතු බව", "තම මතය පමණක් ගත යුතු බව", "ධර්මයේ පවිත්‍රතාව රැක ගැනීමට බුදුරදුන් මෙම පරීක්ෂණ ක්‍රමය දේශනා කළහ."),
    q("පාලි ත්‍රිපිටකයේ සඳහන් අංගුත්තර නිකායේ සූත්‍ර ප්‍රමාණය දළ වශයෙන් කොපමණද?", "නවදහස් පන්සියයකට අධිකය (9,557)", "තිස් හතරකි", "එකසිය පනස් දෙකකි", "පන්සියයකි", "කෙටි හා ඉතා වැදගත් ධර්ම කරුණු රාශියක් අංගුත්තර නිකායේ අන්තර්ගතය."),
    q("ලංකාවේ බෞද්ධ සාහිත්‍යයේ කිසිදා විනාශ නොවී රැකුණු ධම්මපද අටුවාව පාලියට නැගුවේ කවුද?", "බුද්ධඝෝෂ මහතෙරුන් වහන්සේ", "මිහිඳු හිමි", "රාහුල හිමි", "ධර්මසේන හිමි", "ධම්මපදට්ඨකථාව ඇසුරෙන් පසුව සිංහල සද්ධර්මරත්නාවලිය රචනා විය."),
    q("ශ්‍රී ලංකාවේ සිදු වූ ත්‍රිපිටක සංරක්ෂණ කටයුතු අතර 20 වන සියවසේ බිහි වූ 'ශ්‍රී ලංකා ත්‍රිපිටක මුද්‍රණය' ආරම්භ වූයේ කුමන වර්ෂයේද?", "1956 බුද්ධ ජයන්ති වර්ෂයේදී", "1815 දී", "1948 දී", "1972 දී", "ලංකා බෞද්ධ මණ්ඩලයේ මෙහෙයවීමෙන් පාලි පෙළ හා සිංහල පරිවර්තනය මුද්‍රණය කෙරිණි.")
  )
}
